const { useState, useRef } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Search = () => {
  const [keyword, setKeyword] = useState('');
  const typedCount = useRef(0);
  const inputRef = useRef(null);

  console.log('그려집니다. 친 횟수(ref) =', typedCount.current);

  const handleChange = (event) => {
    typedCount.current = typedCount.current + 1;
    console.log('   ref 를', typedCount.current, '로 바꿨습니다');
    setKeyword(event.target.value);
  };

  const clear = () => {
    setKeyword('');
    inputRef.current.focus();
  };

  return (
    <div className="panel">
      <label className="field" htmlFor="q">코스 검색</label>
      <input className="field__input" id="q" type="search" ref={inputRef}
        value={keyword} onChange={handleChange} />
      <p className="note">지금까지 {typedCount.current}번 쳤습니다</p>
      <div className="row">
        <button className="clear" type="button" onClick={clear}>지우고 커서 옮기기</button>
      </div>
    </div>
  );
};

root.render(<Search />);

